"""Contact sheet rows for substitute teachers."""

from rosterkit.errors import ProjectError


def _check_email(student):
    if not student.email:
        raise ProjectError(
            f"No email for {student.display_name}"
        )


def _name_key(student):
    return student.display_name


def _row(student, wide_name, wide_sect):
    name = f"{student.display_name:<{wide_name}}"
    sect = f"{student.section:<{wide_sect}}"
    return f"{name}  {sect}  {student.email}"


def format_contacts(students):
    """Name-sorted rows of name, section and email."""
    if not students:
        raise ProjectError("No students given")
    ordered = sorted(students, key=_name_key)
    for item in ordered:
        _check_email(item)
    names = max(len(item.display_name) for item in ordered)
    sects = max(len(item.section) for item in ordered)
    return [_row(item, names, sects) for item in ordered]

