import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def _student(last, first, mail="a@x.org"):
    return Student("1", last, first, "A", mail)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = format_contacts(
            [_student("Wu", "Al"), _student("Lee", "Bo")]
        )
        self.assertEqual(rows[0], "Lee, Bo  A  a@x.org")
        self.assertEqual(rows[1], "Wu, Al   A  a@x.org")

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as caught:
            format_contacts([_student("Lee", "Bo", None)])
        self.assertIn("Lee, Bo", str(caught.exception))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
